/* Shared header finishes, using the existing navigation and breakpoints. */
body[data-page] .topbar {
  --header-navy: #151b25;
  --header-panel: #202935;
  --header-gold: #eddbb6;
  --header-edge: #887557;
  background-color: var(--header-navy);
  background-image: linear-gradient(110deg, #121822, #242c3a 76%, #1a222e);
  border-bottom-color: var(--header-edge);
  box-shadow: 0 5px 22px #10151d38;
}

body[data-page] .topbar .brand-mark {
  box-shadow: 0 0 0 1px #eddbb61a, 0 4px 12px #080d1566;
}

body[data-page] .topbar :is(.brand-line, .nav-service-description) {
  color: #cdc9c1;
}

body[data-page] .topbar .solutions-menu {
  background-color: var(--header-panel);
  border-color: var(--header-edge);
}

body[data-page] .topbar :is(.nav-menu-label, .nav-dropdown > summary > span) {
  color: var(--header-gold);
}

body[data-page] .topbar :is(.nav-actions > .secondary, [data-nav-toggle]) {
  background-color: #ffffff06;
  border-color: var(--header-edge);
  color: var(--header-gold);
}

body[data-page] .topbar :is(.nav-actions > .secondary, [data-nav-toggle]):is(:hover, [aria-expanded="true"]) {
  background-color: #eddbb614;
  border-color: var(--header-gold);
}

body[data-page] .topbar :is(.nav-actions > .primary, .mobile-demo) {
  background: #dfc38c linear-gradient(115deg, #f4e3be, #dfc38c);
  border-color: #e8d2a3;
  color: #181c23;
  box-shadow: inset 0 1px #fff6dfb3, 0 4px 14px #0b101a60;
}

body[data-page] .topbar :is(.nav-actions > .primary, .mobile-demo):hover {
  background: #ead0a0 linear-gradient(115deg, #fbefd5, #ead0a0);
  border-color: #f2dfb8;
}

body[data-page] .topbar :is(a, summary, button, .button):focus-visible {
  outline-color: var(--header-gold);
}

@media (max-width: 1180px) {
  body[data-page] .topbar .primary-nav {
    background-color: var(--header-navy);
    border-color: var(--header-edge);
  }
}
